#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string word;
    int count = 0;

    ifstream inputFile("input.txt");

    if (inputFile.is_open()) {
        string line;
        while (getline(inputFile, line)) {
            for (int i = 0; i < line.length(); i++) {
                if (line[i] == ' ' && word.empty()) {
                    word = line[i];
                    count = 1;
                } else if (line[i] == ' ' && !word.empty()) {
                    count++;
                }
            }
        }
        inputFile.close();
    } else {
        cout << "Unable to open input file." << endl;
    }

    cout << "Word: " << word << endl;
    cout << "Count: " << count << endl;

    return 0;
}
```
请注意，这个程序假设输入文件中的每个单词都是空格隔开的。如果您的文件中的单词有不同的格式，您需要相应地修改程序。

